(()=>{'use strict';const slides=[...document.querySelectorAll('.slide')],notes=JSON.parse(document.getElementById('notes-data').textContent);function pageFromHash(){const page=Number(location.hash.slice(1));return Number.isFinite(page)?Math.max(0,Math.min(slides.length-1,Math.floor(page||1)-1)):0;}let current=pageFromHash();const byId=x=>document.getElementById(x);function show(){slides.forEach((s,i)=>s.classList.toggle('active',i===current));byId('page-counter').textContent=`${current+1} / ${slides.length}`;byId('prev').disabled=current===0;byId('next').disabled=current===slides.length-1;byId('speaker-notes').textContent=notes[current];try{history.replaceState(null,'','#'+(current+1));}catch{}document.title=`${current+1} / ${slides.length} · ${byId('deck').dataset.chapter||'第一章'}教学演示`;}function move(d){current=Math.max(0,Math.min(slides.length-1,current+d));show();}function toggleNotes(){const el=byId('speaker-notes');el.hidden=!el.hidden;byId('notes-button').setAttribute('aria-expanded',String(!el.hidden));}async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.body.requestFullscreen)await document.body.requestFullscreen();else alert('此浏览器暂不支持页面全屏，可使用浏览器的全屏功能。');}catch{alert('未能进入全屏，可使用浏览器的全屏功能。');}}byId('prev').onclick=()=>move(-1);byId('next').onclick=()=>move(1);byId('notes-button').onclick=toggleNotes;byId('fullscreen').onclick=fullscreen;document.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey||['INPUT','TEXTAREA','SELECT','BUTTON','A'].includes(e.target.tagName))return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();move(1);}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();move(-1);}if(e.key==='Home'){e.preventDefault();current=0;show();}if(e.key==='End'){e.preventDefault();current=slides.length-1;show();}if(e.key.toLowerCase()==='n')toggleNotes();if(e.key.toLowerCase()==='f')fullscreen();});window.addEventListener('hashchange',()=>{current=pageFromHash();show();});show();})();
